<script setup>
import {ref,watch,nextTick} from 'vue';
import {t} from '../state/appearance';
const props=defineProps({chat:{type:Object,required:true},previews:{type:Object,required:true},disabled:Boolean});defineEmits(['page']);const messages=ref();watch(()=>[props.chat.id,props.chat.offset,props.chat.messages.map(m=>m.id+':'+m.text.length).join(',')],async()=>{await nextTick();if(messages.value)messages.value.scrollTop=props.chat.nextOffset<0?messages.value.scrollHeight:0;},{immediate:true});
</script>
<template><section class="conversation" :aria-label="t('История чата','Chat history')"><div v-if="chat.total" class="conversation-pages"><button class="action-button" :disabled="disabled||chat.offset===0" @click="$emit('page',Math.max(0,chat.offset-8))">{{t('Ранее','Earlier')}}</button><span>{{chat.offset+1}}–{{chat.offset+chat.messages.length}} / {{chat.total}}</span><button class="action-button" :disabled="disabled||chat.nextOffset<0" @click="$emit('page',chat.nextOffset)">{{t('Далее','Later')}}</button></div><div ref="messages" class="conversation-messages" aria-live="polite"><article v-for="message in chat.messages" :key="chat.id+':'+message.id" class="conversation-message" :class="message.role"><strong>{{message.role==='user'?t('Вы','You'):message.role==='error'?t('Ошибка','Error'):t('Ассистент','Assistant')}}</strong><p>{{message.text.trim()}}</p><div v-if="message.files" class="conversation-files">{{message.files}}</div><div class="conversation-pictures"><img v-for="file in (previews[chat.id+':'+message.id]||[]).filter(f=>f.mime.startsWith('image/'))" :key="file.dataUrl" :src="file.dataUrl" :alt="file.name"></div></article><span v-if="!chat.total" class="muted">{{t('Сообщения и вложения сохраняются в контексте до «Новый чат».','Messages and attachments remain in context until New chat.')}}</span></div></section></template>
<style scoped>
.conversation{flex:none;max-height:260px;display:flex;flex-direction:column;min-height:0}.conversation-pages{display:flex;align-items:center;gap:8px;font-size:12px}.conversation-messages{overflow:auto;min-height:0}.conversation-message{padding:5px 8px;border-bottom:1px solid var(--lu-border);font-size:13px}.conversation-message.user{background:var(--lu-surface-alt)}.conversation-message.error{color:var(--lu-danger,#b03030)}.conversation-message strong{font-size:12px}.conversation-message p{white-space:pre-wrap;overflow-wrap:anywhere;margin:3px 0}.conversation-files{font-size:12px;overflow-wrap:anywhere}.conversation-pictures{display:flex;gap:5px}.conversation-pictures img{max-width:92px;max-height:64px;object-fit:contain}
</style>
